  "inlineSchema": "// Prisma Schema for StockBridge B2B Godown & Shop Stock Logistics Network\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  shop_owner\n  godown_admin\n}\n\nenum OrderStatus {\n  pending\n  approved\n  partially_fulfilled\n  dispatched\n  delivered\n  rejected\n}\n\nenum MovementType {\n  restock_in\n  dispatch_out\n  sale\n  adjustment\n  damage\n  voice_correction\n}\n\nmodel User {\n  id                 Int      @id @default(autoincrement())\n  name               String   @db.VarChar(120)\n  phone              String   @unique @db.VarChar(20)\n  email              String   @unique @db.VarChar(120)\n  password_hash      String   @db.VarChar(255)\n  role               Role     @default(shop_owner)\n  godown_id          Int? // If shop_owner, linked godown to order from\n  preferred_language String   @default(\"en-IN\") @db.VarChar(10)\n  created_at         DateTime @default(now())\n\n  // Relations\n  linked_godown       Godown?         @relation(\"ShopLinkedGodown\", fields: [godown_id], references: [id], onDelete: SetNull)\n  administered_godown Godown?         @relation(\"GodownAdmin\")\n  shop_stocks         ShopStock[]\n  orders              Order[]         @relation(\"ShopOrders\")\n  stock_movements     StockMovement[] @relation(\"ShopMovements\")\n  voice_logs          VoiceLog[]\n\n  @@index([godown_id])\n  @@map(\"users\")\n}\n\nmodel Godown {\n  id            Int      @id @default(autoincrement())\n  name          String   @db.VarChar(150)\n  location      String   @db.VarChar(255)\n  admin_user_id Int      @unique\n  created_at    DateTime @default(now())\n\n  // Relations\n  admin           User            @relation(\"GodownAdmin\", fields: [admin_user_id], references: [id], onDelete: Cascade)\n  linked_shops    User[]          @relation(\"ShopLinkedGodown\")\n  products        Product[]\n  godown_stocks   GodownStock[]\n  orders          Order[]\n  stock_movements StockMovement[]\n\n  @@map(\"godowns\")\n}\n\nmodel Product {\n  id             Int      @id @default(autoincrement())\n  godown_id      Int\n  name           String   @db.VarChar(150)\n  aliases        String?  @db.Text\n  category       String   @db.VarChar(100)\n  unit           String   @db.VarChar(30) // kg, l, pcs, box, packet\n  price_per_unit Decimal  @db.Decimal(10, 2)\n  created_at     DateTime @default(now())\n\n  // Relations\n  godown          Godown          @relation(fields: [godown_id], references: [id], onDelete: Cascade)\n  godown_stock    GodownStock?\n  shop_stocks     ShopStock[]\n  order_items     OrderItem[]\n  stock_movements StockMovement[]\n\n  @@index([godown_id])\n  @@map(\"products\")\n}\n\nmodel GodownStock {\n  id                 Int      @id @default(autoincrement())\n  product_id         Int      @unique\n  godown_id          Int\n  quantity_available Decimal  @default(0.00) @db.Decimal(12, 2)\n  last_updated       DateTime @updatedAt\n\n  // Relations\n  product Product @relation(fields: [product_id], references: [id], onDelete: Cascade)\n  godown  Godown  @relation(fields: [godown_id], references: [id], onDelete: Cascade)\n\n  @@index([godown_id])\n  @@map(\"godown_stock\")\n}\n\nmodel ShopStock {\n  id                Int      @id @default(autoincrement())\n  shop_user_id      Int\n  product_id        Int\n  quantity_on_hand  Decimal  @default(0.00) @db.Decimal(12, 2)\n  reorder_threshold Decimal  @default(10.00) @db.Decimal(12, 2)\n  last_updated      DateTime @updatedAt\n\n  // Relations\n  shop_user User    @relation(fields: [shop_user_id], references: [id], onDelete: Cascade)\n  product   Product @relation(fields: [product_id], references: [id], onDelete: Cascade)\n\n  @@unique([shop_user_id, product_id])\n  @@index([shop_user_id])\n  @@index([product_id])\n  @@map(\"shop_stock\")\n}\n\nmodel Order {\n  id             Int         @id @default(autoincrement())\n  shop_user_id   Int\n  godown_id      Int\n  status         OrderStatus @default(pending)\n  total_amount   Decimal     @default(0.00) @db.Decimal(12, 2)\n  source         String      @default(\"manual\") @db.VarChar(50)\n  raw_transcript String?     @db.Text\n  created_at     DateTime    @default(now())\n  updated_at     DateTime    @updatedAt\n\n  // Relations\n  shop_user       User            @relation(\"ShopOrders\", fields: [shop_user_id], references: [id], onDelete: Cascade)\n  godown          Godown          @relation(fields: [godown_id], references: [id], onDelete: Cascade)\n  items           OrderItem[]\n  stock_movements StockMovement[]\n\n  @@index([shop_user_id])\n  @@index([godown_id])\n  @@index([status])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id            Int     @id @default(autoincrement())\n  order_id      Int\n  product_id    Int\n  qty_requested Decimal @db.Decimal(12, 2)\n  qty_fulfilled Decimal @default(0.00) @db.Decimal(12, 2)\n  unit_price    Decimal @db.Decimal(10, 2)\n\n  // Relations\n  order   Order   @relation(fields: [order_id], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [product_id], references: [id], onDelete: Cascade)\n\n  @@index([order_id])\n  @@index([product_id])\n  @@map(\"order_items\")\n}\n\nmodel StockMovement {\n  id                 Int          @id @default(autoincrement())\n  product_id         Int\n  godown_id          Int?\n  shop_user_id       Int?\n  movement_type      MovementType\n  quantity           Decimal      @db.Decimal(12, 2) // Positive or recorded delta\n  reference_order_id Int?\n  raw_transcript     String?      @db.Text\n  created_at         DateTime     @default(now())\n\n  // Relations\n  product         Product @relation(fields: [product_id], references: [id], onDelete: Cascade)\n  godown          Godown? @relation(fields: [godown_id], references: [id], onDelete: SetNull)\n  shop_user       User?   @relation(\"ShopMovements\", fields: [shop_user_id], references: [id], onDelete: SetNull)\n  reference_order Order?  @relation(fields: [reference_order_id], references: [id], onDelete: SetNull)\n\n  @@index([product_id])\n  @@index([godown_id])\n  @@index([shop_user_id])\n  @@index([reference_order_id])\n  @@map(\"stock_movements\")\n}\n\nmodel VoiceLog {\n  id                Int      @id @default(autoincrement())\n  user_id           Int\n  raw_transcript    String   @db.Text\n  detected_intent   String   @db.VarChar(100)\n  detected_language String   @db.VarChar(20)\n  confidence        Decimal  @db.Decimal(5, 4)\n  action_taken      String?  @db.Text\n  created_at        DateTime @default(now())\n\n  user User @relation(fields: [user_id], references: [id], onDelete: Cascade)\n\n  @@index([user_id])\n  @@map(\"voice_logs\")\n}\n",
